use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

/// Provenance metadata read from `<image>.openimg.json` sidecars generated by OpenIMG.
/// Used strictly for provenance, file identity, and preservation on export — never as
/// proof of visual furniture grouping.
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OpenImgSidecar {
    pub purpose: Option<String>,
    pub asset_id: Option<String>,
    pub attempt_id: Option<String>,
    pub source_file_name: Option<String>,
    pub source_sha256: Option<String>,
    pub generated_sha256: Option<String>,
    pub candidate_sha256: Option<String>,
    pub operation_id: Option<String>,
    pub automated_decision: Option<String>,
    pub is_latest_attempt: Option<bool>,
    pub copied_at: Option<String>,
    pub exported_at: Option<String>,
}

impl OpenImgSidecar {
    /// Returns the SHA-256 of the image produced by OpenIMG when present in the sidecar.
    pub fn effective_image_sha256(&self) -> Option<&str> {
        self.generated_sha256
            .as_deref()
            .filter(|s| !s.is_empty())
            .or_else(|| self.candidate_sha256.as_deref().filter(|s| !s.is_empty()))
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SidecarInfo {
    pub path: PathBuf,
    pub data: OpenImgSidecar,
}

/// Returns the expected OpenIMG sidecar path (`<image_path>.openimg.json`).
pub fn sidecar_path_for(image_path: &Path) -> PathBuf {
    let mut os = image_path.as_os_str().to_os_string();
    os.push(".openimg.json");
    PathBuf::from(os)
}

/// Loads and parses `<image_path>.openimg.json` if present and valid JSON.
pub fn load_sidecar(image_path: &Path) -> Option<SidecarInfo> {
    let candidate = sidecar_path_for(image_path);
    if !candidate.is_file() {
        return None;
    }
    let bytes = std::fs::read(&candidate).ok()?;
    let data: OpenImgSidecar = serde_json::from_slice(&bytes).ok()?;
    Some(SidecarInfo {
        path: candidate,
        data,
    })
}
